INSERT INTO recipes (id, name, ingredients, instructions, tags, serves) VALUES
(121, 'Butter Bean Stew', '[{"section_title":"Main","items":[{"name":"olive oil","quantity":"2","unit":"tbsp"},{"name":"onion","quantity":"1","unit":"","notes":"chopped"},{"name":"garlic","quantity":"1","unit":"","notes":"crushed or finely sliced"},{"name":"carrots","quantity":"2","unit":"","notes":"cut into small cubes"},{"name":"celery stick","quantity":"1","unit":"","notes":"cut in small pieces"},{"name":"leek","quantity":"1","unit":"","notes":"finely sliced"},{"name":"sugar","quantity":"1/2","unit":"tsp"},{"name":"paprika","quantity":"1/2","unit":"tsp"},{"name":"oregano","quantity":"1/2","unit":"tsp"},{"name":"chilli flakes","quantity":"1/2","unit":"tsp","notes":"(optional)"},{"name":"basil","quantity":"1/2","unit":"tsp"},{"name":"garlic granules","quantity":"1/2","unit":"tsp"},{"name":"tomato paste","quantity":"1","unit":"tbsp"},{"name":"vegetable bouillon cube","quantity":"1","unit":""},{"name":"butter beans","quantity":"3 x 230g","unit":"","notes":"(drained weight), drained and washed"},{"name":"bay leaf","quantity":"1","unit":""},{"name":"plum tomatoes","quantity":"1","unit":"can (400g)"},{"name":"fresh thyme","quantity":"Handful","unit":""},{"name":"dill","quantity":"Handful","unit":""},{"name":"Salt and pepper","quantity":"","unit":"","notes":"to taste"}]}]', '["In a large pot, on a medium heat, sauté the onions, garlic, carrots, celery and leeks with the oil, until translucent. This will take 7-8 minutes, stir occasionally.","Add the sugar and sauté for a minute to caramelize the veggies.","Continue with the veggie cube, tomato paste and dried herbs. Sauté for a minute before you add the butter beans, bay leaf and plum tomatoes.","Break the tomatoes with a wooden spoon and add 400ml of boiling water.","Bring to boil and simmer covered for 30 minutes, stirring occasionally.","Check the seasoning and add the fresh herbs.","Serve with kalamata olives, onions and bread of choice (I used garlic bread). You can keep it in the fridge for up to 5 days and you can also freeze it."]', '["stew","bean","vegetarian","batch-cook","vegan"]', '4'),
(122, 'Root Vegetable Stew with Herb Dumplings', '[{"section_title":"Stew","items":[{"name":"olive oil","quantity":"1","unit":"tbsp"},{"name":"medium onion","quantity":"1","unit":"","notes":"finely sliced"},{"name":"parsnips","quantity":"300g","unit":"","notes":"peeled and cut into bite-sized chunks"},{"name":"carrots","quantity":"300g","unit":"","notes":"peeled and cut into bite-sized chunks"},{"name":"swede","quantity":"300g","unit":"","notes":"peeled and cut into bite-sized chunks"},{"name":"large potato","quantity":"1","unit":"","notes":"peeled and cut into chunks"},{"name":"garlic clove","quantity":"1","unit":"","notes":"crushed"},{"name":"smoked paprika","quantity":"1","unit":"tsp"},{"name":"tomato purée","quantity":"1","unit":"tbsp"},{"name":"plain flour","quantity":"1","unit":"tbsp"},{"name":"hot vegetable stock","quantity":"600ml","unit":"(approx)"},{"name":"bay leaf","quantity":"1","unit":""}]},{"section_title":"Dumplings","items":[{"name":"plain flour","quantity":"100g","unit":""},{"name":"baking powder","quantity":"1/2","unit":"tsp"},{"name":"vegetarian suet","quantity":"25g","unit":""},{"name":"freshly chopped dill","quantity":"2","unit":"tbsp"},{"name":"freshly chopped curly parsley","quantity":"2","unit":"tbsp"},{"name":"creamed horseradish","quantity":"2","unit":"tsp"}]}]', '["Preheat oven to 180°C (160°C fan) mark 4. Heat the oil in a flameproof casserole (that has a lid) and fry the onion for 10min until softened. Add the vegetables and fry for 5min. Add the garlic and cook for 1min.","Stir in the paprika, tomato purée and 1tbsp flour. Cook for 1min, then pour in the vegetable stock - the vegetables should be just covered. Add the bay leaf. Cover with a lid and cook in the oven for 20min.","To make the dumplings, sift the remaining flour, baking powder and 1/2 tsp salt into a large bowl. Stir in the suet, herbs, horseradish and about 75ml (3fl oz) iced water to make a soft dough. Shape into 8 balls and place on top of the stew. Cover and return to the oven for 15min, then remove lid and cook for 5min.","Remove bay leaf and serve."]', '["stew","vegetarian","dumplings","winter"]', '4'),
(123, 'Spinach and Ricotta Stuffed Pasta', '[{"section_title":"Main","items":[{"name":"red onion","quantity":"1","unit":"","notes":"roughly chopped"},{"name":"garlic cloves","quantity":"2","unit":"","notes":"crushed"},{"name":"celery stick","quantity":"1","unit":"","notes":"roughly chopped"},{"name":"tomatoes","quantity":"500g","unit":"","notes":"roughly chopped"},{"name":"olive oil","quantity":"2","unit":"tbsp"},{"name":"chopped tomatoes","quantity":"1 x 400g","unit":"tin"},{"name":"balsamic vinegar","quantity":"2","unit":"tbsp"},{"name":"caster sugar","quantity":"1","unit":"tsp"},{"name":"freshly chopped basil","quantity":"Large Handful","unit":""},{"name":"large pasta shells","quantity":"250g","unit":""},{"name":"spinach","quantity":"200g","unit":""},{"name":"ricotta","quantity":"250g","unit":""},{"name":"full-fat cream cheese","quantity":"100g","unit":""},{"name":"egg","quantity":"1","unit":""},{"name":"freshly grated nutmeg","quantity":"1","unit":"tsp"},{"name":"grated Italian-style hard cheese","quantity":"50g","unit":""}]}]', '["Start by making the tomato sauce, preheat oven to 200°C (180°C fan) mark 6. In a large roasting tin, toss together the onion, garlic, celery and fresh tomatoes with the olive oil and plenty of seasoning. Roast in the oven for 30min.","Scrape the roasted vegetables into a blender and whizz until smooth. Transfer to a large saucepan and mix together with the chopped tomatoes, balsamic vinegar, sugar and most of the basil. Bring to the boil, turn down heat and simmer for 15min.","Meanwhile, bring a large pan of lightly salted water to the boil and cook the pasta for 5-7min until al dente. Drain and rinse with cold water to cool.","Put the spinach in a large colander and pour over a kettle full of just boiled water. Leave until cool enough to handle. Lifting up handfuls at a time, firmly squeeze out any liquid from the wilted spinach. Chop the spinach and transfer to a large bowl.","Stir the ricotta, cream cheese, egg, nutmeg and 1/2 the grated cheese and remaining basil into the spinach. Season to taste.","Pour the tomato sauce into a shallow 2.3 litre (4 pint) ovenproof dish. Divide the cheese mixture among the cooled pasta shells, being careful not to break them. Lay them, in a single layer, in the tomato sauce. Sprinkle over the remaining grated cheese.","Cover with foil and cook in the oven for 30min, covered, before removing foil and cooking for a further 15min."]', '["pasta","vegetarian","bake","spinach","ricotta"]', '4'),
(124, 'Smashed Spiced Jacket Potatoes', '[{"section_title":"Main","items":[{"name":"baking potatoes","quantity":"4","unit":""},{"name":"dried chilli flakes","quantity":"1","unit":"tsp"},{"name":"sweet paprika","quantity":"1","unit":"tsp"},{"name":"vegetable oil","quantity":"2","unit":"tbsp"},{"name":"garlic cloves","quantity":"2","unit":"","notes":"peeled and crushed"},{"name":"lemon","quantity":"1","unit":"","notes":"Zest and juice of"},{"name":"Salt and pepper","quantity":"","unit":""},{"name":"cheddar","quantity":"100g","unit":"grated"},{"name":"tins tuna","quantity":"2 x 110g","unit":"","notes":"drained"},{"name":"mayonnaise","quantity":"2","unit":"tbsp"},{"name":"spring onions","quantity":"2","unit":"","notes":"trimmed and sliced"}]}]', '["Pierce the potatoes all over with a fork, then put them on a microwave-safe plate and microwave for eight to 10 minutes at 800W. Meanwhile, heat a baking tray in an oven set to 210C (190C fan)/gas 6½.","In a small bowl, mix the spices, oil, garlic, lemon zest and juice, then season.","Once the potatoes are out of the microwave - they should be slightly soft - remove the baking tray from the oven and put the potatoes on it. Using the base of a bowl or mug, apply some pressure to the spuds, just enough to smush them, but not completely flat.","Use a spoon or pastry brush to coat the potatoes in the spiced oil, then roast for 25 minutes, until crisp and golden.","Put a small handful of grated cheddar on top of each potato and return to the oven for five to 10 minutes, until the cheese is melted and bubbling.","In a small bowl, mix the drained tuna, mayo and sliced spring onion, and season well. Serve each smashed, cheesy spud topped with a quarter of the tuna mix."]', '["potato","tuna","jacket potato"]', '4'),
(125, 'Potato Rösti', '[{"section_title":"Main","items":[{"name":"medium-sized waxy potatoes","quantity":"2","unit":""},{"name":"Salt and pepper","quantity":"","unit":""},{"name":"butter","quantity":"1","unit":"tbsp"},{"name":"goose fat","quantity":"1","unit":"tbsp","notes":"(or other fat)"}]}]', '["Put the unpeeled waxy potatoes in a pan of well-salted water, bring to a boil, then cook until they''re just tender.","Drain, leave to cool, then chill for at least a couple of hours.","Coarsely grate the potatoes, skins and all, then season generously with salt and black pepper, and toss to combine.","Find a frying pan of about 25cm in diameter. Add half the fats. Put the pan on a medium-high heat until the fats are sizzling, then add the potato strands.","Quickly spread them out to cover the pan, then cook undisturbed for a couple of minutes. Using a spatula, shape the potato mixture into a flat cake, pressing down on it as lightly as possible.","Leave to cook for about 10 minutes more, until the underside is golden and crisp.","Put a heatproof plate over the top of the pan, then turn the pan over so the rösti now sits cooked side up on the plate.","Put the remaining butter and goose fat in the hot pan and, once they''re sizzling, slide the potato cake pale side down back into the pan.","Cook for another 10 minutes, or until that side, too, is golden, then serve at once."]', '["potato","side","vegetarian"]', '4 as a side'),
(126, 'Baked Tunworth with garlic, rosemary & vermouth', '[{"section_title":"Main","items":[{"name":"Tunworth cheese or Camembert","quantity":"250g","unit":"pack"},{"name":"large clove garlic","quantity":"1","unit":"","notes":"cut into slivers"},{"name":"rosemary sprig","quantity":"1","unit":"","notes":"torn into smaller sprigs"},{"name":"vermouth","quantity":"1½","unit":"tbsp"},{"name":"frozen White Rustic Baguettes","quantity":"3","unit":""},{"name":"Chutney, mixed radishes, red grapes","quantity":"","unit":"","notes":"to serve (optional)"}]}]', '["Preheat the oven to 200°C, gas mark 6. Unwrap the cheese, discard the wrapping, and put the cheese back in the box. Tie kitchen string around the whole thing to secure it while cooking.","Use a sharp knife to make a few long crosswise cuts in the cheese. Push the garlic slivers and rosemary sprigs into the cuts. Grind over some black pepper, then put the cheese, in its box, on one side of a large baking tray and pour over the vermouth. Bake for 10 minutes.","After 10 minutes, put the frozen baguettes on the other side of the baking tray and return the tray to the oven for a further 10 minutes until the cheese is gooey and the bread baked.","Slice the baguettes and serve on a board or platter with the cheese and chutney, radishes and grapes, if liked."]', '["cheese","baked","starter","vegetarian"]', '6 as a starter'),
(127, 'Chickpea stew with tomatoes & spinach', '[{"section_title":"Main","items":[{"name":"vegetable oil","quantity":"1","unit":"tbsp"},{"name":"red onion","quantity":"1","unit":"","notes":"sliced"},{"name":"garlic cloves","quantity":"2","unit":"","notes":"chopped"},{"name":"fresh root ginger","quantity":"finger length piece","unit":"","notes":"shredded"},{"name":"mild red chillies","quantity":"2","unit":"","notes":"thinly sliced"},{"name":"turmeric","quantity":"½","unit":"tsp"},{"name":"garam masala","quantity":"1","unit":"tsp"},{"name":"ground cumin","quantity":"1","unit":"tsp"},{"name":"tomatoes","quantity":"4","unit":"","notes":"chopped"},{"name":"tomato purée","quantity":"2","unit":"tsp"},{"name":"chickpea","quantity":"400g","unit":"can, rinsed and drained"},{"name":"baby spinach leaves","quantity":"200g","unit":""},{"name":"rice or naan bread","quantity":"","unit":"","notes":"to serve"}]}]', '["Heat the oil in a wok and fry the onion over a low heat until softened. Stir in the garlic, ginger and chillies and cook for a further 5 mins until the onions are golden and the garlic slightly toasted.","Add the turmeric, garam masala and cumin, stirring over a low heat for a few secs. Tip in the chopped tomatoes and add the tomato purée, then simmer for 5 mins.","Add the chickpeas to the pan with 300ml water (fill the can three-quarters full). Simmer for 10 mins before stirring in the spinach to wilt. Season and serve with rice or naan."]', '["stew","chickpea","vegetarian","vegan"]', '4'),
(128, 'Patatas bravas with grated tomato and cumin', '[{"section_title":"Main","items":[{"name":"waxy potatoes (e.g., yukon gold)","quantity":"800g","unit":"","notes":"peeled and cut into 3cm pieces"},{"name":"olive oil","quantity":"75ml","unit":""},{"name":"Fine sea salt and black pepper","quantity":"","unit":""},{"name":"plum tomatoes","quantity":"3","unit":"(320g)"},{"name":"garlic clove","quantity":"1","unit":"","notes":"peeled and crushed"},{"name":"plain flour","quantity":"1/2","unit":"tsp"},{"name":"sweet smoked paprika","quantity":"2","unit":"tsp"},{"name":"hot smoked paprika","quantity":"1","unit":"tsp"},{"name":"plain yoghurt","quantity":"60ml","unit":"","notes":"at room temperature"},{"name":"cumin seeds","quantity":"1","unit":"tsp","notes":"toasted and lightly crushed"}]}]', '["Heat the oven to 200C (180C fan)/gas 6. Toss the potatoes, two tablespoons of oil and three-quarters of a teaspoon of salt on a large lined baking tray, then roast for 30 minutes, until golden and cooked through.","Meanwhile, grate the tomatoes on the rough side of a box grater, then discard the spent skins; you should end up with about 220g grated flesh.","Transfer the grated tomato to a sieve set over a bowl and season the pulp with the garlic and a half-teaspoon of salt. Leave to drain for five minutes, stirring once or twice, then transfer the pulp to a second bowl and season with two tablespoons of oil and a good crack of pepper.","Measure the tomato liquid in the bowl under the sieve, top it up with cold water to bring it to 175ml, then set aside.","For the bravas sauce, put the flour and the remaining tablespoon of oil in a small pan on a medium-high heat and cook, stirring, for a minute, until it turns into a bubbling paste.","Stir in both paprikas, cook for another 30 seconds, until fragrant but not burnt, then slowly stir in the tomato water. Simmer until the sauce reduces to a thick, double cream-like consistency.","Transfer the oven-hot potatoes and the bravas sauce to a large bowl, and toss to combine. Layer the mix on a medium platter, spoon the yoghurt, tomato pulp and cumin on top, and serve at once."]', '["potato","tapas","vegetarian","side"]', '4'),
(129, 'Eggplant mesa''a''ah (Egyptian spiced eggplant)', '[{"section_title":"Main","items":[{"name":"large eggplants","quantity":"2","unit":"","notes":"sliced into 2cm-thick rounds"},{"name":"extra virgin olive oil","quantity":"2 1/2","unit":"tbs"},{"name":"onion","quantity":"1","unit":"","notes":"thinly sliced"},{"name":"garlic cloves","quantity":"6","unit":"","notes":"thinly sliced"},{"name":"tomato paste","quantity":"1","unit":"tbs"},{"name":"ground cumin","quantity":"1","unit":"tsp"},{"name":"ground coriander","quantity":"1","unit":"tsp"},{"name":"very ripe tomatoes","quantity":"500g","unit":"","notes":"roughly chopped"},{"name":"caster sugar","quantity":"1","unit":"tsp"},{"name":"Salt","quantity":"","unit":"","notes":"for eggplants"},{"name":"Olive oil","quantity":"","unit":"","notes":"extra to fry"},{"name":"Chargrilled pita bread","quantity":"","unit":"","notes":"to serve"}]}]', '["Salt eggplants liberally all over and stand in a colander set over a bowl for 1 hour.","Heat 2 1/2 tbs oil in a large saucepan over medium-high heat. Add onion and garlic and cook, stirring frequently, for 4-5 minutes until onion begins to soften.","Reduce heat to medium and stir in tomato paste and cook, stirring frequently, for a further 5-6 minutes until paste begins to catch at the bottom of the pan.","Stir in spices, tomato and sugar. Cook, stirring occasionally, for 6-8 minutes until tomato begins to break down and most of the liquid has become thick and glossy.","Wash off the salt from the eggplant and pat dry.","Heat 2cm of the extra olive oil in a large frypan, and in batches, fry eggplant for 2-3 minutes, turning halfway, until golden. Drain on a paper towel and repeat with remaining eggplant. Top up with more oil if needed.","Add cooked eggplant to the tomato sauce in the pan and cook very gently on low heat for 15-20 minutes until sauce looks split and oily.","Serve immediately or refrigerate overnight and serve cold with some chargrilled pita bread."]', '["eggplant","vegetarian","vegan","middle eastern"]', '10'),
(130, 'Vodka gochujang rigatoni', '[{"section_title":"Main","items":[{"name":"rapeseed oil","quantity":"2","unit":"tbsp"},{"name":"red onion","quantity":"1","unit":"","notes":"peeled and very finely sliced"},{"name":"fine sea salt","quantity":"1","unit":"tsp"},{"name":"garlic cloves","quantity":"2","unit":"","notes":"peeled and grated"},{"name":"passata (or finely chopped tinned tomatoes)","quantity":"1 x 400g","unit":"jar"},{"name":"gochujang","quantity":"1","unit":"tbsp"},{"name":"tomato puree","quantity":"1","unit":"tbsp"},{"name":"vodka","quantity":"100ml","unit":""},{"name":"oat-based single cream","quantity":"175ml","unit":"","notes":"e.g., Oatly"},{"name":"rigatoni","quantity":"400g","unit":""}]}]', '["Put the oil in a large frying pan on a medium-to-high heat, add the onion and salt, and fry, stirring, for eight minutes, until the onion is soft enough to cut easily with a wooden spoon.","Add the garlic, fry for two minutes, then add the passata, gochujang, tomato puree and half the vodka, and leave it all to bubble away for 10 minutes, until the mix is quite paste-like.","Add the cream and the rest of the vodka, stir, simmer for a couple of minutes, then take off the heat.","Cook the rigatoni for a minute less than the packet instructions. Carefully scoop a mug (about 250ml) of the cooking water out of the pasta pan, put to one side, then drain the pasta.","Pop the sauce back on the heat, add the pasta and all the reserved cooking water, stir and let it all bubble away for a couple of minutes, until the sauce is nice and thick and clinging to the pasta. Taste for seasoning, add a little salt, if need be, and serve hot."]', '["pasta","vegetarian","vegan","gochujang"]', '2'),
(131, 'Twice baked potatoes', '[{"section_title":"Main","items":[{"name":"large baking potatoes","quantity":"4","unit":""},{"name":"butter","quantity":"40g","unit":""},{"name":"soured cream or crème fraîche","quantity":"180ml","unit":""},{"name":"mature Cheddar","quantity":"120g","unit":"grated"},{"name":"spring onions","quantity":"2-3","unit":"","notes":"trimmed and thinly sliced"},{"name":"Sea salt and freshly ground black pepper","quantity":"","unit":""}]}]', '["Preheat the oven to 200°C/Gas Mark 6. Place the potatoes on a baking sheet and cook for about an hour, until tender when pierced with a knife. Remove from the oven but leave the oven on.","When the potatoes are just cool enough to handle, carefully halve them lengthways - you might want to wrap them in a tea towel when you do this - and scoop out most of the insides into a bowl, leaving a shell about 5mm thick. Return these shells to the oven to crisp up while you make the filling (don''t let them cook for more than 10 minutes).","Mash the scooped-out potato with the butter, then stir in the soured cream or crème fraîche, Cheddar and spring onions. Season generously with salt and pepper.","Spoon the mixture back into the shells and bake until heated through, about 10-15 minutes. Cool slightly before serving."]', '["potato","jacket potato","vegetarian"]', '4'),
(132, 'Sticky roasted broccoli fried rice', '[{"section_title":"Broccoli","items":[{"name":"gluten-free soy sauce","quantity":"1","unit":"tbsp"},{"name":"dark brown sugar","quantity":"1","unit":"tbsp"},{"name":"sesame oil","quantity":"3","unit":"tbsp"},{"name":"large broccoli","quantity":"1","unit":"","notes":"cut into medium florets"}]},{"section_title":"Rice","items":[{"name":"uncooked long-grain rice","quantity":"275g","unit":""},{"name":"eggs","quantity":"2","unit":"","notes":"lightly beaten with a pinch of salt"},{"name":"vegetable oil","quantity":"4","unit":"tbsp"},{"name":"red peppers","quantity":"2","unit":"","notes":"chopped"},{"name":"carrots","quantity":"2","unit":"","notes":"chopped"},{"name":"gluten-free soy sauce","quantity":"3","unit":"tbsp"},{"name":"dark brown sugar","quantity":"1","unit":"tbsp"},{"name":"spring onion greens","quantity":"A handful","unit":"","notes":"finely chopped"}]}]', '["Cook the rice to the packet instructions - steamed works best. Once cooked, drain if needed and leave to cool completely. Cover and chill in the fridge overnight.","The next day, heat the oven to 220C (200C fan)/gas 7. In a small bowl, mix the soy sauce and dark brown sugar for the broccoli.","Drizzle the sesame oil over a large baking tray, then roll the broccoli in it until well coated. Put in the oven for five minutes, then pour over the soy sauce mix and coat the broccoli. Return to the oven for eight to 10 minutes.","(To cook in an air fryer, heat to 180C and remove the crisping tray. Put the broccoli in the air fryer for three minutes, then pour on the soy mix and coat the broccoli. Return to the air fryer for five to six minutes.)","Make the fried rice. Put the vegetable oil in a wok, on a medium-high heat. Once hot, add the red pepper and carrots and stir-fry until lightly browned.","Add the beaten egg, leave it to cook for around 30 seconds, then break up the egg into chunks.","Add the cooked rice and stir to break it up. Add the soy sauce and sugar, and stir again so the rice is nicely coated. Stir-fry for another five minutes or until the rice starts to look crisp in places.","Serve the fried rice topped with the roasted broccoli and chopped spring onions."]', '["rice","fried rice","vegetarian","broccoli"]', '4'),
(133, 'Baked garlic mushroom rice', '[{"section_title":"Mushrooms","items":[{"name":"mushrooms","quantity":"450g","unit":""},{"name":"garlic-infused oil","quantity":"3","unit":"tbsp"}]},{"section_title":"Rice","items":[{"name":"uncooked long-grain rice","quantity":"275g","unit":""},{"name":"vegetable stock","quantity":"500ml","unit":"boiling hot"},{"name":"dried thyme","quantity":"1","unit":"tbsp"},{"name":"dried or fresh parsley","quantity":"1/2","unit":"tbsp"},{"name":"salt","quantity":"1","unit":"tsp"},{"name":"white or black pepper","quantity":"1/2","unit":"tsp"},{"name":"extra mature cheddar","quantity":"50g","unit":"grated"},{"name":"chives","quantity":"A small handful","unit":"","notes":"finely chopped, to serve"},{"name":"Rocket salad","quantity":"","unit":"","notes":"to serve"}]}]', '["Heat the oven to 200C (180C fan)/gas 6. In a small bowl, combine the mushrooms and garlic-infused oil.","Put all the ingredients for the rice (apart from the chives and rocket) in a 23cm x 33cm roasting dish and mix well.","Lay the mushrooms on top and put in the oven for 40 minutes.","Top with chives and serve with rocket."]', '["rice","bake","mushroom","vegetarian"]', '4'),
(134, 'Spicy merguez oven chips with yoghurt dip', '[{"section_title":"Spice Mix","items":[{"name":"cumin seeds","quantity":"1","unit":"tsp"},{"name":"fennel seeds","quantity":"1","unit":"tsp"},{"name":"coriander seeds","quantity":"1","unit":"tsp"},{"name":"caraway seeds","quantity":"1/2","unit":"tsp","notes":"(optional)"},{"name":"black peppercorns","quantity":"10-12","unit":""},{"name":"sweet smoked paprika","quantity":"1/2","unit":"tsp"},{"name":"cayenne pepper","quantity":"A pinch","unit":""},{"name":"fine sea salt","quantity":"1/4","unit":"tsp"}]},{"section_title":"Chips","items":[{"name":"potatoes","quantity":"~1kg","unit":""},{"name":"rapeseed or olive oil","quantity":"3","unit":"tbsp"}]},{"section_title":"Dip","items":[{"name":"plain (full-fat) yoghurt","quantity":"6","unit":"heaped tbsp"},{"name":"garlic","quantity":"~1/4","unit":"clove","notes":"crushed with a little salt"},{"name":"cayenne","quantity":"A pinch","unit":"","notes":"to sprinkle"}]}]', '["Preheat the oven to 200°C/Gas Mark 6.","For the spice mix, crush the cumin, fennel, coriander and caraway seeds, if using, with the black peppercorns to a powder, using a pestle and mortar. Combine with the paprika, cayenne and salt.","Give the potatoes a good scrub (you don''t need to peel them), then cut into thick chips. Put them into a saucepan and cover with cold water. Bring to a rolling boil and boil for 1 minute, then immediately drain well.","Pour the oil in a large, shallow roasting dish and put into the oven for 5 minutes to heat up.","Set aside about 1 heaped teaspoon of the spice mix. Add the rest to the drained potatoes and toss together.","Take the hot roasting dish from the oven, add the spiced potatoes and turn to coat in the oil. Roast for 35-45 minutes, giving a stir halfway through, until golden and crisp.","For the dip, stir the remaining spice mix into the yoghurt with the crushed garlic. Transfer to a serving bowl and sprinkle with a pinch of cayenne.","Test one of the spicy chips to see if they need sprinkling with a little more salt, then serve them hot, with the cool yoghurt dip."]', '["potato","chips","vegetarian","side"]', '4'),
(135, 'Tomato and bean soup', '[{"section_title":"Main","items":[{"name":"olive oil","quantity":"2","unit":"tbsp"},{"name":"red onions","quantity":"2","unit":"","notes":"finely chopped"},{"name":"garlic cloves","quantity":"3","unit":"","notes":"finely chopped"},{"name":"medium-hot green chillies (e.g., jalapeño)","quantity":"1-2","unit":"","notes":"deseeded and finely chopped"},{"name":"ground cumin","quantity":"1","unit":"tsp"},{"name":"vegetable stock","quantity":"500ml","unit":""},{"name":"roasted tomato sauce or passata","quantity":"200ml","unit":""},{"name":"ripe tomatoes","quantity":"500g","unit":"","notes":"cored, deseeded and finely chopped"},{"name":"black beans or black eyed beans","quantity":"400g","unit":"tin, drained and rinsed"},{"name":"oregano","quantity":"A handful","unit":"","notes":"chopped"},{"name":"sugar","quantity":"A pinch","unit":""},{"name":"lime","quantity":"1","unit":"Juice of"},{"name":"coriander","quantity":"A small handful","unit":"","notes":"roughly chopped"},{"name":"Salt and freshly ground black pepper","quantity":"","unit":""}]},{"section_title":"To Finish","items":[{"name":"soured cream","quantity":"4-6","unit":"tbsp","notes":"(optional)"},{"name":"coriander","quantity":"A small handful","unit":"","notes":"roughly chopped"},{"name":"reserved red onion","quantity":"a little","unit":""}]}]', '["Heat the olive oil in a saucepan over a medium-low heat, add most of the onions (reserving a little to finish the soup) and sauté for about 5 minutes, or until softened. Add the garlic, chillies and cumin and stir for a minute.","Add the stock, roasted tomato sauce or passata, tomatoes, beans, oregano and sugar. Season with salt and pepper, bring to the boil and simmer gently for 10 minutes.","Remove from the heat and add the lime juice and coriander. Taste and adjust the seasoning if necessary.","Serve the soup topped with dollops of soured cream, if you like, and scattered with the reserved red onion, chopped coriander and freshly ground pepper."]', '["soup","bean","vegetarian","vegan"]', '4-6'),
(136, 'Pesto baked eggs', '[{"section_title":"Main","items":[{"name":"mozzarella","quantity":"50g","unit":"grated"},{"name":"vegetarian green pesto","quantity":"2","unit":"tbsp"},{"name":"eggs","quantity":"2","unit":""},{"name":"Salt and black pepper","quantity":"","unit":""},{"name":"chilli flakes","quantity":"1/2","unit":"tsp"},{"name":"thick slices sourdough","quantity":"2","unit":""},{"name":"olive oil","quantity":"2","unit":"tbsp"}]}]', '["Heat the oven to 180C (160C fan)/gas 4.","Divide the grated mozzarella between two ovenproof ramekins, top each with a tablespoon of pesto, then crack an egg into each.","Season with salt, pepper and chilli flakes, then bake for 12 minutes, until the egg is cooked but the yolk is still runny.","Meanwhile, brush each slice of sourdough with olive oil and toast in a dry frying pan on a medium-high heat for two minutes on each side.","Season the toasted sourdough, then cut into soldiers.","Serve the baked pesto eggs, hot out of the oven, with the sourdough soldiers for dipping."]', '["eggs","baked","vegetarian","breakfast"]', '2'),
(137, 'Fish finger katsu curry', '[{"section_title":"Katsu Sauce","items":[{"name":"vegetable oil","quantity":"1","unit":"tbsp"},{"name":"onion","quantity":"1/2","unit":"","notes":"finely chopped"},{"name":"carrot","quantity":"75g","unit":"","notes":"diced"},{"name":"garlic cloves","quantity":"2","unit":"","notes":"peeled and very finely chopped"},{"name":"peeled and finely grated fresh root ginger","quantity":"1","unit":"tsp"},{"name":"garam masala","quantity":"1","unit":"tsp"},{"name":"ground turmeric","quantity":"1 1/2","unit":"tsp"},{"name":"honey","quantity":"2","unit":"tbsp"},{"name":"soy sauce","quantity":"1","unit":"tbsp"},{"name":"vegetable stock","quantity":"400ml","unit":""}]},{"section_title":"Main","items":[{"name":"fish fingers","quantity":"6","unit":""},{"name":"jasmine rice","quantity":"120g","unit":""}]},{"section_title":"To Serve (optional)","items":[{"name":"Coriander","quantity":"","unit":""},{"name":"Sesame seeds","quantity":"","unit":""},{"name":"Baby spinach leaves","quantity":"","unit":""},{"name":"Butterhead lettuce leaves","quantity":"","unit":""},{"name":"Raw carrot ribbons","quantity":"","unit":""}]}]', '["Heat the oven to 230C (210C fan)/gas 8. Put the fish fingers on an oven tray and bake for 12 minutes.","Meanwhile, cook the rice according to the packet instructions.","Make the katsu sauce: heat the oil in a frying pan on a low-medium heat, then sweat the onion, carrot, garlic and ginger with the garam masala and turmeric for five minutes.","Stir in the honey and soy sauce, then add the stock. Increase the heat, bring the sauce to a boil, then turn down to a simmer and cook for 10 minutes, until the sauce has thickened.","If you prefer a smoother sauce, use a stick blender to blitz it to a silky consistency. Taste and season accordingly.","Serve the fish fingers with a mound of rice and the katsu curry sauce spooned generously over the top. Sprinkle with coriander and sesame seeds, if you like, and/or with a side salad for added colour."]', '["fish fingers","katsu","curry"]', '2'),
(138, 'Roasted tomato, pepper & rocket pasta', '[{"section_title":"Main","items":[{"name":"mixed baby tomatoes","quantity":"2 x 250g","unit":"packs, destalked"},{"name":"mixed Romano peppers","quantity":"200g","unit":"pack, deseeded and sliced"},{"name":"large red onion","quantity":"1","unit":"","notes":"sliced"},{"name":"garlic cloves","quantity":"6","unit":"","notes":"sliced"},{"name":"nonpareille capers","quantity":"1 1/2","unit":"tbsp","notes":"drained and rinsed"},{"name":"sherry vinegar","quantity":"50ml","unit":""},{"name":"oregano","quantity":"1 x 15g","unit":"pack, leaves only"},{"name":"olive oil","quantity":"2","unit":"tbsp"},{"name":"wholewheat fusilli","quantity":"300g","unit":""},{"name":"pine nuts","quantity":"4","unit":"tbsp"},{"name":"rocket","quantity":"1 x 90g","unit":"pack"}]}]', '["Preheat the oven to 220°C, gas mark 7. In a large roasting tin, toss together the tomatoes, peppers, onion, garlic, capers, sherry vinegar, oregano and olive oil; season. Roast for 25-30 minutes, tossing everything halfway through cooking.","When the vegetables have 15 minutes left, bring a large pan of salted water to the boil and cook the pasta for the shortest time on the pack instructions.","Spread the pine nuts out on a small baking tray and roast for 3 minutes, until golden. Tip onto a plate and set aside.","Use a slotted spoon to transfer the pasta to the vegetable tin, allowing some of the water to travel across too. Add the rocket; toss everything together, adding more pasta water if needed. Scatter over the pine nuts and serve."]', '["pasta","vegetarian","vegan","roast"]', '4'),
(139, 'Cauliflower cheese', '[{"section_title":"Sauce","items":[{"name":"onion","quantity":"1","unit":""},{"name":"cloves","quantity":"2","unit":""},{"name":"milk","quantity":"1","unit":"litre"},{"name":"bay leaves","quantity":"2","unit":""},{"name":"butter","quantity":"75g","unit":""},{"name":"plain flour","quantity":"50g","unit":""},{"name":"lancashire cheese","quantity":"100g","unit":"grated"},{"name":"double cream","quantity":"75ml","unit":""},{"name":"Nutmeg","quantity":"","unit":"freshly grated"},{"name":"Salt and pepper","quantity":"","unit":""}]},{"section_title":"Main","items":[{"name":"medium-large cauliflower","quantity":"1","unit":""},{"name":"white bread","quantity":"4","unit":"slices, crusts removed, blitzed into breadcrumbs"},{"name":"cheddar","quantity":"25g","unit":"grated"}]}]', '["Infuse the milk: Peel the onion, then cut in half and stud with the cloves. Put in a small pan with the milk and bay leaves, bring slowly to a simmer, then turn off the heat, cover and leave to sit and infuse for at least 15 minutes, before removing and discarding the onion, cloves and bay.","Make the white sauce: Melt 50g of the butter in a medium pan set over a medium-low heat, then whisk in the flour and cook, stirring, for a couple of minutes. Gradually add some of the infused milk, stirring it in to make a paste, then stir in the remaining milk, turn down the heat and simmer, stirring, until you have a thick sauce.","Add the cheese: Crumble or grate the lancashire into the sauce until it melts. Add the cream and a good grating of nutmeg or black pepper, season to taste, then keep warm on a very low heat.","Prepare the cauliflower: Bring a large pan of well-salted water to a boil. Cut the cauliflower into generous florets. Trim off and discard any tough bits of stalk, and cut the remaining stalk into even chunks.","Parboil the cauliflower: Put the florets and chunks of stalk into the pan of boiling water and cook for four to five minutes, until just tender, but not soft. Scoop out with a slotted spoon and drain well.","Fry the cauliflower: Melt most of the remaining 25g butter in a large frying pan on a medium-high heat, then fry the cauliflower, stirring, until slightly browned and caramelised. Season and spoon into a baking dish.","Assemble and grill: Put the remaining butter in the same pan and, once melted, add the breadcrumbs and fry until crunchy and golden. Season. Heat the grill to medium-high. Pour the warm cheese sauce over the cauliflower, then grate the cheddar on top. Sprinkle with the breadcrumbs, then grill until golden and bubbling. Serve immediately."]', '["cauliflower","cheese","vegetarian","side"]', '4'),
(140, 'Sun-Dried Tomato Pasta', '[{"section_title":"Pasta","items":[{"name":"pasta (penne or fusilli)","quantity":"250g","unit":""},{"name":"salt","quantity":"1 1/2","unit":"tsp"}]},{"section_title":"Sauce","items":[{"name":"olive oil","quantity":"2","unit":"tbsp"},{"name":"tomato paste","quantity":"2","unit":"tbsp"},{"name":"garlic (small)","quantity":"4","unit":"cloves","notes":"mashed"},{"name":"black pepper","quantity":"1 1/2","unit":"tsp"},{"name":"cumin","quantity":"A pinch","unit":""},{"name":"oregano","quantity":"A pinch","unit":""},{"name":"paprika","quantity":"1 1/2","unit":"tsp"},{"name":"red pepper flakes","quantity":"1/4","unit":"tsp"},{"name":"sun-dried tomatoes","quantity":"1","unit":"cup","notes":"chopped"},{"name":"fresh mint","quantity":"1","unit":"tbsp","notes":"chopped (optional)"},{"name":"fresh basil","quantity":"1 1/2","unit":"cup","notes":"chopped"}]}]', '["Cook pasta according to packet instructions with salt.","While pasta is cooking, make the sauce. Heat olive oil in a pan. Add tomato paste and mashed garlic and cook for a minute.","Add black pepper, cumin, oregano, paprika, and red pepper flakes. Stir.","Add chopped sun-dried tomatoes and cook for 2-3 minutes.","Drain the pasta, reserving some pasta water.","Add the drained pasta to the sauce pan. Stir to combine. Add a splash of pasta water if needed to loosen.","Stir in fresh mint (if using) and fresh basil. Serve immediately."]', '["pasta","vegetarian","vegan","sun-dried tomato"]', '4'),
(141, 'Baked camembert', '[{"section_title":"Main","items":[{"name":"camembert or brie","quantity":"250g","unit":""},{"name":"vermouth, or dry white wine, or kirsch","quantity":"1","unit":"tbsp"},{"name":"thyme sprigs","quantity":"2","unit":""},{"name":"dried chilli flakes","quantity":"pinch","unit":""},{"name":"crackers or toasted bread","quantity":"","unit":"","notes":"to serve"}]}]', '["Heat oven to 200C/180C fan/gas 6 or heat your air fryer to 180C for 4 mins.","Unwrap the camembert from its packaging, then place back into its box. Tie string around the box to secure. If using a cheese that doesn''t have a box, put into a ramekin or other ovenproof dish.","Slash the cheese a few times and top with vermouth, dry white wine or kirsch, thyme sprigs and a pinch of dried chilli flakes.","Bake on a baking tray for 20 mins, or if using an air-fryer, cook for 15-20 mins until gooey. Serve with toasted bread or crackers for dipping."]', '["cheese","baked","starter","vegetarian"]', '4-6');